import { useMemo, type JSX } from 'react';
import {
  HOST_SERVICE_IDS,
  getHostService,
  type AdminShellSectionWrapper,
  type HostContext,
} from '@cedros/data-react/admin';
import {
  CedrosLoginAdminRuntimeContext,
  type CedrosLoginAdminRuntimeValue,
} from './CedrosLoginAdminRuntimeContext';
import {
  AuthStateContext,
  AuthUIContext,
  CedrosLoginContext,
  type AuthStateContextValue,
  type AuthUIContextValue,
  type CedrosLoginContextValue,
} from '../context/CedrosLoginContext';
import { getDefaultFeatureFlags, isFeatureEnabled as resolveFeatureEnabled } from '../featureFlags';
import type { AuthUser, CedrosLoginConfig } from '../types';

const NOOP = () => {};
const NOOP_ASYNC = async () => {};

type CedrosLoginHostService = NonNullable<HostContext['cedrosLogin']>;

function normalizeAdminUser(
  user: CedrosLoginHostService['user']
): AuthUser | null {
  return user
    ? {
        authMethods: [],
        emailVerified: false,
        createdAt: '',
        updatedAt: '',
        ...user,
      }
    : null;
}

function buildCedrosLoginAdminRuntimeValue(
  hostContext: HostContext
): CedrosLoginAdminRuntimeValue | null {
  const cedrosLogin = getHostService<CedrosLoginHostService>(
    hostContext,
    HOST_SERVICE_IDS.cedrosLogin
  );
  if (!cedrosLogin) {
    return null;
  }

  const user = normalizeAdminUser(cedrosLogin.user);

  return {
    config: {
      serverUrl: cedrosLogin.serverUrl,
    },
    user,
    authState: user ? 'authenticated' : 'unauthenticated',
    getAccessToken: cedrosLogin.getAccessToken,
  };
}

function buildCedrosLoginContextValue(
  adminRuntime: CedrosLoginAdminRuntimeValue
): CedrosLoginContextValue {
  const featureFlags = getDefaultFeatureFlags();
  const config: CedrosLoginConfig = {
    ...adminRuntime.config,
  };

  return {
    config,
    featureFlags,
    isFeatureEnabled: (name) => resolveFeatureEnabled(name, { flags: featureFlags }),
    user: adminRuntime.user,
    authState: adminRuntime.authState,
    error: null,
    logout: NOOP_ASYNC,
    refreshUser: NOOP_ASYNC,
    isModalOpen: false,
    openModal: NOOP,
    closeModal: NOOP,
    _internal: {
      handleLoginSuccess: NOOP,
      getAccessToken: adminRuntime.getAccessToken,
      getReferralCode: () => null,
    },
  };
}

export const CedrosLoginAdminSectionWrapper: AdminShellSectionWrapper = ({
  children,
  hostContext,
}): JSX.Element => {
  const adminRuntimeValue = useMemo(
    () => buildCedrosLoginAdminRuntimeValue(hostContext),
    [hostContext]
  );
  const combinedValue = useMemo(
    () => (adminRuntimeValue ? buildCedrosLoginContextValue(adminRuntimeValue) : null),
    [adminRuntimeValue]
  );

  if (!combinedValue) {
    return <>{children}</>;
  }

  const { error, isModalOpen, openModal, closeModal, ...authStateValue } = combinedValue;
  const uiValue: AuthUIContextValue = {
    error,
    isModalOpen,
    openModal,
    closeModal,
  };

  return (
    <CedrosLoginAdminRuntimeContext.Provider value={adminRuntimeValue}>
      <AuthStateContext.Provider value={authStateValue as AuthStateContextValue}>
        <AuthUIContext.Provider value={uiValue}>
          <CedrosLoginContext.Provider value={combinedValue}>{children}</CedrosLoginContext.Provider>
        </AuthUIContext.Provider>
      </AuthStateContext.Provider>
    </CedrosLoginAdminRuntimeContext.Provider>
  );
};
